import java.util.Scanner;

public class Main {
    static boolean tubmi(long n) {
        if (n < 2) return false;
        for (long d = 2; d * d <= n; d++) {
            if (n % d == 0) return false;
        }
        return true;
    }

    static long[] natija(long[] a) {
        long son = 0;
        long yigindi = 0;
        for (long x : a) {
            if (tubmi(x)) {
                son++;
                yigindi += x;
            }
        }
        return new long[]{son, yigindi};
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = in.nextLong();
        long[] s = natija(a);
        System.out.println(s[0] + " " + s[1]);
    }
}

